import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    out = []
    out_append = out.append

    for _ in range(t):
        R = int(data[idx])
        B = int(data[idx + 1])
        idx += 2

        if R + B < 2 or (R & 1) or (R == 0 and (B & 1)):
            out_append("No")
            continue

        if R == 2 and B == 3:
            out_append("Yes")
            out_append("B 2 3")
            out_append("R 3 2" + " ")
            out_append("B 2 2")
            out_append("B 3 3")
            out_append("R 2 4")
            continue

        pieces = []
        append = pieces.append

        if R == 0:
            # Blue-only cycle in (a,b) coordinates: r = a + b, c = a - b.
            l = B // 2 - 1
            for b in range(l + 1):
                append(('B', b, -b))
            for b in range(l, -1, -1):
                append(('B', 1 + b, 1 - b))

        elif B == 0:
            # Red-only rectangle perimeter.
            l = R // 2 - 1
            for c in range(l + 1):
                append(('R', 0, c))
            for c in range(l, -1, -1):
                append(('R', 1, c))

        else:
            if B & 1:
                # Mixed, B odd: meet at C = (1, 1).
                k = R // 2
                for c in range(k + 1):
                    append(('R', 0, c))
                for c in range(k, 1, -1):
                    append(('R', 1, c))
                append(('B', 1, 1))

                l = B // 2
                for b in range(1, l + 1):
                    append(('B', 1 + b, 1 - b))
                for b in range(l, 0, -1):
                    append(('B', b, -b))

            else:
                # Mixed, B even: meet at C = (2, 0).
                if R == 2:
                    append(('R', 0, 0))
                    append(('R', 1, 0))
                else:
                    m = (R - 2) // 2
                    for c in range(m + 1):
                        append(('R', 0, c))
                    append(('R', 1, m))
                    for c in range(m, 0, -1):
                        append(('R', 2, c))

                append(('B', 2, 0))

                l = B // 2
                for b in range(2, l + 1):
                    append(('B', 1 + b, 1 - b))
                for b in range(l, 0, -1):
                    append(('B', b, -b))

        min_r = min(p[1] for p in pieces)
        min_c = min(p[2] for p in pieces)
        off_r = 1 - min_r
        off_c = 1 - min_c

        out_append("Yes")
        for color, r, c in pieces:
            out_append(f"{color} {r + off_r} {c + off_c}")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

from typing import List
from bisect import bisect_right

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        if not queries:
            return 0

        max_r = max(r for _, r in queries)

        # powers[i] = 4^i, with the last power strictly greater than max_r
        powers = [1]
        while powers[-1] <= max_r:
            powers.append(powers[-1] * 4)

        # pref[i] = sum of d(x) for x in [1, 4^i - 1]
        pref = [0] * len(powers)
        for i in range(1, len(powers)):
            pref[i] = pref[i - 1] + (powers[i] - powers[i - 1]) * i

        def prefix(n: int) -> int:
            """Sum of d(x) for x in [1, n]."""
            if n <= 0:
                return 0
            i = bisect_right(powers, n) - 1
            # d(x) = i + 1 on [4^i, 4^(i+1) - 1]
            return pref[i] + (n - powers[i] + 1) * (i + 1)

        def depth(x: int) -> int:
            """Number of floor divisions by 4 needed to make x zero."""
            return bisect_right(powers, x)

        ans = 0
        for l, r in queries:
            total_depth = prefix(r) - prefix(l - 1)
            max_depth = depth(r)
            ans += max((total_depth + 1) // 2, max_depth)

        return ans

import sys

def main():
    s = sys.stdin.buffer.readline().strip()
    n = len(s)
    if n == 0:
        return

    r = s[::-1]

    # Prefix function for the pattern r only.
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        c = r[i]
        while j > 0 and c != r[j]:
            j = pi[j - 1]
        if c == r[j]:
            j += 1
        pi[i] = j

    # KMP scan of s with pattern r.
    # q is the length of the longest prefix of r that is a suffix of s.
    q = 0
    for c in s:
        while q > 0 and r[q] != c:
            q = pi[q - 1]
        if r[q] == c:
            q += 1
            if q == n:
                break

    k = n - q
    sys.stdout.buffer.write(s + s[:k][::-1] + b"\n")

if __name__ == "__main__":
    main()

import sys
from functools import lru_cache


def predict(n, feats):
    m, p, x, i, o, f = feats

    if n & 1:
        return (m & 1) == 1

    # Even N.
    if o == 0:
        return ((p + (i // 2)) & 1) == 1

    if o <= 2:
        return True

    return p != f


def solve_large(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * n
    comp = [-1] * n
    comp_info = []

    for s in range(n):
        if color[s] != -1:
            continue

        cid = len(comp_info)
        color[s] = 0
        comp[s] = cid
        stack = [s]
        a = 1
        b = 0

        while stack:
            u = stack.pop()
            cu = color[u]
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = cu ^ 1
                    comp[v] = cid
                    if color[v] == 0:
                        a += 1
                    else:
                        b += 1
                    stack.append(v)

        comp_info.append((a + b, a, b))

    c = len(comp_info)
    e_count = [0] * c
    for u, v in edges:
        e_count[comp[u]] += 1

    p = 0
    x = 0
    i = 0
    o = 0
    f = 0

    for cid, (size, a, b) in enumerate(comp_info):
        p ^= (a * b - e_count[cid]) & 1

        if size == 1:
            x += 1
            i += 1
        elif size & 1:
            x += 1
            o += 1
        else:
            if a & 1:
                f ^= 1

    return predict(n, (len(edges), p, x, i, o, f))


def reduced_dp(max_c=16):
    @lru_cache(maxsize=None)
    def win(state):
        i, o, e0, e1, p = state

        # Internal move: adding a missing edge inside a component toggles p.
        # Only p=1 -> p=0 is needed for P/N determination.
        if p == 1:
            if not win((i, o, e0, e1, 0)):
                return True

        # isolated + isolated -> odd/odd even component, p unchanged
        if i >= 2:
            if not win((i - 2, o, e0, e1 + 1, p)):
                return True

        # isolated + odd -> even/even with p toggled, or odd/odd with p unchanged
        if i >= 1 and o >= 1:
            if not win((i - 1, o - 1, e0 + 1, e1, 1 - p)):
                return True
            if not win((i - 1, o - 1, e0, e1 + 1, p)):
                return True

        # isolated + even/even -> odd component, p toggled
        if i >= 1 and e0 >= 1:
            if not win((i - 1, o + 1, e0 - 1, e1, 1 - p)):
                return True

        # isolated + odd/odd -> odd component, p unchanged
        if i >= 1 and e1 >= 1:
            if not win((i - 1, o + 1, e0, e1 - 1, p)):
                return True

        # odd + odd -> even/even with p toggled, or odd/odd with p unchanged
        if o >= 2:
            if not win((i, o - 2, e0 + 1, e1, 1 - p)):
                return True
            if not win((i, o - 2, e0, e1 + 1, p)):
                return True

        # odd + even/even -> odd component, p toggled
        if o >= 1 and e0 >= 1:
            if not win((i, o, e0 - 1, e1, 1 - p)):
                return True

        # odd + odd/odd -> odd component, p unchanged
        if o >= 1 and e1 >= 1:
            if not win((i, o, e0, e1 - 1, p)):
                return True

        # even/even + even/even -> even/even, p toggled
        if e0 >= 2:
            if not win((i, o, e0 - 1, e1, 1 - p)):
                return True

        # even/even + odd/odd -> odd/odd, p toggled
        if e0 >= 1 and e1 >= 1:
            if not win((i, o, e0 - 1, e1, 1 - p)):
                return True

        # odd/odd + odd/odd -> even/even, p toggled
        if e1 >= 2:
            if not win((i, o, e0 + 1, e1 - 2, 1 - p)):
                return True

        return False

    states = []
    for i in range(max_c + 1):
        for o in range(max_c + 1 - i):
            for e0 in range(max_c + 1 - i - o):
                for e1 in range(max_c + 1 - i - o - e0):
                    if (i + o) & 1:
                        continue
                    for p in (0, 1):
                        states.append((i, o, e0, e1, p))

    mismatches = []
    for s in states:
        i, o, e0, e1, p = s
        x = i + o
        f = e1 & 1
        pred_win = predict(2, (0, p, x, i, o, f))
        dp_win = win(s)
        if pred_win != dp_win:
            mismatches.append((s, dp_win, pred_win))

    print(f"Reduced even-N DP max_c={max_c}")
    print(f"states={len(states)} mismatches={len(mismatches)}")
    if mismatches:
        for s, dp_win, pred_win in mismatches[:20]:
            print(f"mismatch state={s} dp={dp_win} predict={pred_win}")

    specific = [(0, 4, 0, 1, 1), (0, 6, 0, 0, 0)]
    for s in specific:
        w = win(s)
        print(f"specific state {s} losing={not w}")
        if w:
            print("ERROR: specific state is winning")


