from typing import List
from itertools import permutations
import math
import random


class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10 ** 18

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            if fact[i - 1] > CAP // i:
                fact[i] = CAP
            else:
                fact[i] = fact[i - 1] * i

        def cap_mul(a: int, b: int) -> int:
            if a == 0 or b == 0:
                return 0
            if a >= CAP or b >= CAP:
                return CAP
            if a > CAP // b:
                return CAP
            return a * b

        odd_count = (n + 1) // 2
        even_count = n // 2

        total = cap_mul(fact[odd_count], fact[even_count])
        if n % 2 == 0:
            total = cap_mul(total, 2)

        if total < k:
            return []

        used = [False] * (n + 1)
        rem_odd = odd_count
        rem_even = even_count
        ans = []
        prev_parity = -1

        for pos in range(n):
            future_len = n - pos - 1
            chosen = False

            for x in range(1, n + 1):
                if used[x]:
                    continue

                p = x & 1
                if prev_parity != -1 and p == prev_parity:
                    continue

                if p:
                    no = rem_odd - 1
                    ne = rem_even
                else:
                    no = rem_odd
                    ne = rem_even - 1

                if no < 0 or ne < 0:
                    continue

                req_next = 1 - p
                if req_next:
                    need_odd = (future_len + 1) // 2
                else:
                    need_odd = future_len // 2
                need_even = future_len - need_odd

                if no == need_odd and ne == need_even:
                    block = cap_mul(fact[no], fact[ne])

                    if k > block:
                        k -= block
                    else:
                        ans.append(x)
                        used[x] = True
                        rem_odd = no
                        rem_even = ne
                        prev_parity = p
                        chosen = True
                        break

            if not chosen:
                return []

        return ans


def _brute_alternating(n: int) -> List[List[int]]:
    res = []
    for perm in permutations(range(1, n + 1)):
        ok = True
        for i in range(n - 1):
            if (perm[i] & 1) == (perm[i + 1] & 1):
                ok = False
                break
        if ok:
            res.append(list(perm))
    res.sort()
    return res


def _is_valid(perm: List[int], n: int) -> bool:
    if len(perm) != n:
        return False
    if sorted(perm) != list(range(1, n + 1)):
        return False
    for i in range(n - 1):
        if (perm[i] & 1) == (perm[i + 1] & 1):
            return False
    return True


def _rank(perm: List[int], n: int) -> int:
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i

    used = [False] * (n + 1)
    rem_odd = (n + 1) // 2
    rem_even = n // 2
    rank = 1
    prev_parity = -1

    for pos, x in enumerate(perm):
        future_len = n - pos - 1

        for cand in range(1, x):
            if used[cand]:
                continue

            cp = cand & 1
            if prev_parity != -1 and cp == prev_parity:
                continue

            if cp:
                no = rem_odd - 1
                ne = rem_even
            else:
                no = rem_odd
                ne = rem_even - 1

            if no < 0 or ne < 0:
                continue

            req_next = 1 - cp
            if req_next:
                need_odd = (future_len + 1) // 2
            else:
                need_odd = future_len // 2
            need_even = future_len - need_odd

            if no == need_odd and ne == need_even:
                rank += fact[no] * fact[ne]

        if x & 1:
            rem_odd -= 1
        else:
            rem_even -= 1
        used[x] = True
        prev_parity = x & 1

    return rank


def _fail(msg: str) -> None:
    raise RuntimeError(msg)


def _run_verification() -> None:
    sol = Solution()

    examples = [
        (4, 6, [3, 4, 1, 2]),
        (3, 2, [3, 2, 1]),
        (2, 3, []),
    ]
    for n, k, expected in examples:
        got = sol.permute(n, k)
        if got != expected:
            _fail(f"example n={n} k={k}: got {got}, expected {expected}")

    # Brute-force check for small n. Testing every k from 1 to total+1
    # includes k=1, k=total, k=total+1, and all block-boundary values.
    for n in range(1, 9):
        expected = _brute_alternating(n)
        total = len(expected)
        for k in range(1, total + 2):
            got = sol.permute(n, k)
            if k <= total:
                if got != expected[k - 1]:
                    _fail(f"brute n={n} k={k}: got {got}, expected {expected[k - 1]}")
            else:
                if got != []:
                    _fail(f"brute n={n} k={k}: expected [], got {got}")

    # Independent rank-based sanity checks for slightly larger n.
    rng = random.Random(12345)
    for n in range(1, 13):
        odd = (n + 1) // 2
        even = n // 2
        total = math.factorial(odd) * math.factorial(even)
        if n % 2 == 0:
            total *= 2

        limit = min(total, 10 ** 15)
        test_ks = {1, limit, limit + 1, total, total + 1}
        for _ in range(25):
            test_ks.add(rng.randint(1, limit))

        for k in sorted(test_ks):
            got = sol.permute(n, k)
            if k <= total:
                if not _is_valid(got, n):
                    _fail(f"rank n={n} k={k}: invalid permutation {got}")
                r = _rank(got, n)
                if r != k:
                    _fail(f"rank n={n} k={k}: computed rank {r}, expected {k}")
            else:
                if got != []:
                    _fail(f"rank n={n} k={k}: expected [], got {got}")

    print("verification passed")


if __name__ == "__main__":
    _run_verification()

from typing import List
from itertools import combinations


class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        C = 4 * side

        def perimeter_coord(pt: List[int]) -> int:
            x, y = pt
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 3 * side - x
            return 4 * side - y

        p = sorted(perimeter_coord(pt) for pt in points)
        n = len(p)
        p2 = p + [x + C for x in p]
        nxt = [0] * (2 * n)
        all_indices = range(2 * n)
        starts = range(n)
        jump_range = range(k - 1)

        def can(D: int) -> bool:
            if D == 0:
                return True

            pp = p2
            nn = n
            mm = 2 * nn
            CC = C
            nnxt = nxt
            all_idx = all_indices
            st = starts
            jr = jump_range

            j = 1
            for i in all_idx:
                if j <= i:
                    j = i + 1
                target = pp[i] + D
                while j < mm and pp[j] < target:
                    j += 1
                nnxt[i] = j

            for s in st:
                idx = s
                limit = s + nn
                for _ in jr:
                    idx = nnxt[idx]
                    if idx >= limit:
                        break
                else:
                    if pp[s] + CC - pp[idx] >= D:
                        return True
            return False

        lo, hi = 0, min(side, C // k)
        ans = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if can(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans


def _boundary_points(side: int) -> List[List[int]]:
    pts: List[List[int]] = []
    for x in range(side + 1):
        pts.append([x, 0])
        pts.append([x, side])
    for y in range(1, side):
        pts.append([0, y])
        pts.append([side, y])
    return pts


def _brute_force(points: List[List[int]], k: int) -> int:
    n = len(points)
    if k <= 1:
        return 0

    dist = [[0] * n for _ in range(n)]
    for i in range(n):
        xi, yi = points[i]
        for j in range(i + 1, n):
            xj, yj = points[j]
            d = abs(xi - xj) + abs(yi - yj)
            dist[i][j] = d
            dist[j][i] = d

    best = 0
    for comb in combinations(range(n), k):
        md = 10**18
        for a in range(k - 1):
            ia = comb[a]
            dia = dist[ia]
            for b in range(a + 1, k):
                d = dia[comb[b]]
                if d < md:
                    if d <= best:
                        md = d
                        break
                    md = d
            if md <= best:
                break
        if md > best:
            best = md
    return best


def _run_self_tests() -> None:
    from random import Random

    sol = Solution()

    assert sol.maxDistance(2, [[0, 2], [2, 0], [2, 2], [0, 0]], 4) == 2
    assert sol.maxDistance(2, [[0, 0], [1, 2], [2, 0], [2, 2], [2, 1]], 4) == 1
    assert sol.maxDistance(2, [[0, 0], [0, 1], [0, 2], [1, 2], [2, 0], [2, 2], [2, 1]], 5) == 1

    # Exhaustive cross-check for all subsets of the small side=1 and side=2 squares.
    for side in (1, 2):
        all_pts = _boundary_points(side)
        total = len(all_pts)
        for mask in range(1, 1 << total):
            pts = [all_pts[i] for i in range(total) if mask & (1 << i)]
            n = len(pts)
            if n < 4:
                continue
            for k in range(4, n + 1):
                expected = _brute_force(pts, k)
                got = sol.maxDistance(side, pts, k)
                if got != expected:
                    raise AssertionError(
                        f"side={side} mask={mask} k={k}: got {got}, expected {expected}"
                    )

    # Full boundary sets for side 1..4.
    for side in range(1, 5):
        pts = _boundary_points(side)
        n = len(pts)
        for k in {4, n}:
            if 4 <= k <= n:
                expected = _brute_force(pts, k)
                got = sol.maxDistance(side, pts, k)
                if got != expected:
                    raise AssertionError(
                        f"full side={side} k={k}: got {got}, expected {expected}"
                    )

    # Deterministic random cross-check for side <= 4.
    rng = Random(20240525)
    for _ in range(30):
        side = rng.randint(1, 4)
        all_pts = _boundary_points(side)
        n = rng.randint(4, len(all_pts))
        pts = rng.sample(all_pts, n)
        k = rng.randint(4, min(n, 25))

        expected = _brute_force(pts, k)
        got = sol.maxDistance(side, pts, k)
        if got != expected:
            raise AssertionError(
                f"side={side} k={k} pts={pts} got={got} expected={expected}"
            )


if __name__ == "__main__":
    _run_self_tests()

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        blocks = [part for part in parts if part != '']
        n = len(s)

        # If all literal parts are empty, the empty substring matches.
        if not blocks:
            return 0

        occ_cache = {}

        def get_occ(block):
            if block not in occ_cache:
                occ_cache[block] = self._kmp_occurrences(s, block)
            return occ_cache[block]

        occs = [get_occ(block) for block in blocks]

        # If any required literal block does not occur, no match is possible.
        for occ in occs:
            if not occ:
                return -1

        k = len(blocks)

        # Only one literal block: the shortest match is the block itself.
        if k == 1:
            return len(blocks[0])

        INF = n + 1

        def build_next(occ):
            """
            nxt[i] = earliest occurrence start >= i, or INF if none.
            occ must be sorted ascending.
            """
            nxt = [INF] * (n + 1)
            j = len(occ) - 1
            cur = INF
            for i in range(n, -1, -1):
                if j >= 0 and occ[j] == i:
                    cur = i
                    j -= 1
                nxt[i] = cur
            return nxt

        next_cache = {}

        def get_next(block, occ):
            if block not in next_cache:
                next_cache[block] = build_next(occ)
            return next_cache[block]

        if k == 2:
            x, y = blocks
            next_y = get_next(y, occs[1])
            best = INF
            lx, ly = len(x), len(y)

            for sx in occs[0]:
                sy = next_y[sx + lx]
                if sy != INF:
                    cand = sy + ly - sx
                    if cand < best:
                        best = cand

            return -1 if best == INF else best

        # k == 3
        x, y, z = blocks
        next_y = get_next(y, occs[1])
        next_z = get_next(z, occs[2])
        best = INF
        lx, ly, lz = len(x), len(y), len(z)

        for sx in occs[0]:
            sy = next_y[sx + lx]
            if sy == INF:
                continue
            sz = next_z[sy + ly]
            if sz == INF:
                continue
            cand = sz + lz - sx
            if cand < best:
                best = cand

        return -1 if best == INF else best

    def _kmp_occurrences(self, s: str, pat: str) -> list:
        n = len(s)
        m = len(pat)

        if m == 0 or m > n:
            return []

        # Prefix function for KMP.
        pi = [0] * m
        j = 0
        for i in range(1, m):
            while j > 0 and pat[i] != pat[j]:
                j = pi[j - 1]
            if pat[i] == pat[j]:
                j += 1
            pi[i] = j

        occ = []
        j = 0
        for i, ch in enumerate(s):
            while j > 0 and ch != pat[j]:
                j = pi[j - 1]
            if ch == pat[j]:
                j += 1
            if j == m:
                occ.append(i - m + 1)
                j = pi[j - 1]

        return occ

