    def brute(intervals):
        n = len(intervals)
        best_w = -1
        best = None
        for k in range(1, min(4, n) + 1):
            for comb in combinations(range(n), k):
                ok = True
                for a in range(k):
                    for b in range(a + 1, k):
                        i, j = comb[a], comb[b]
                        l1, r1, _ = intervals[i]
                        l2, r2, _ = intervals[j]
                        if not (r1 < l2 or r2 < l1):
                            ok = False
                            break
                    if not ok:
                        break
                if not ok:
                    continue
                w = 0
                for i in comb:
                    w += intervals[i][2]
                lst = list(comb)
                if w > best_w or (w == best_w and (best is None or lst < best)):
                    best_w = w
                    best = lst
        return best if best is not None else []

