import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])

    bounds = {}
    idx = 2

    for _ in range(M):
        x = int(data[idx])
        y = int(data[idx + 1])
        c = data[idx + 2]
        idx += 3

        if x in bounds:
            l, u = bounds[x]
        else:
            l, u = 0, N

        if c == b'B':
            if y > l:
                l = y
        else:
            v = y - 1
            if v < u:
                u = v

        bounds[x] = (l, u)

    max_l = 0

    for x in sorted(bounds.keys(), reverse=True):
        l, u = bounds[x]
        if l > max_l:
            max_l = l
        if max_l > u:
            sys.stdout.write("No\n")
            return

    sys.stdout.write("Yes\n")

if __name__ == "__main__":
    main()

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    K = int(data[0]); S = data[1]; T = data[2]
    n0, m0 = len(S), len(T)
    if abs(n0 - m0) > K:
        print('No'); return

    i = 0; lim = min(n0, m0)
    while i < lim and S[i] == T[i]:
        i += 1
    j = 0; lim = min(n0 - i, m0 - i)
    while j < lim and S[n0 - 1 - j] == T[m0 - 1 - j]:
        j += 1

    S = S[i:n0 - j]; T = T[i:m0 - j]
    n, m = len(S), len(T)

    if n == 0 and m == 0:
        print('Yes'); return
    if n == 0 or m == 0:
        print('Yes' if abs(n - m) <= K else 'No'); return

    cache = {}; CH = 8192

    def lcp(x, y):
        if x < 0 or y < 0 or x >= n or y >= m:
            return 0
        key = (x, y)
        if key in cache:
            return cache[key]

        max_l = min(n - x, m - y); l = 0
        ss = S; tt = T; ch = CH

        while max_l >= ch:
            b = tt[y:y + ch]
            if ss.startswith(b, x):
                x += ch; y += ch; l += ch; max_l -= ch
            else:
                a = ss[x:x + ch]
                z = int.from_bytes(a, 'little') ^ int.from_bytes(b, 'little')
                l += ((z & -z).bit_length() - 1) // 8
                cache[key] = l; return l

        if max_l:
            b = tt[y:y + max_l]
            if ss.startswith(b, x):
                l += max_l
            else:
                a = ss[x:x + max_l]
                z = int.from_bytes(a, 'little') ^ int.from_bytes(b, 'little')
                l += ((z & -z).bit_length() - 1) // 8

        cache[key] = l; return l

    size = 2 * K + 1; off = K; dp = [-1] * size
    dp[off] = lcp(0, 0)
    if dp[off] == n and dp[off] == m:
        print('Yes'); return

    for e in range(1, K + 1):
        ndp = [-1] * size
        for d in range(-e, e + 1):
            best = -1

            idx = off + d
            if 0 <= idx < size:
                v = dp[idx]
                if v >= 0 and v < n and 0 <= v + d < m:
                    best = v + 1

            idx = off + d - 1
            if 0 <= idx < size:
                v = dp[idx]
                if v >= 0 and 0 <= v + d - 1 < m and v > best:
                    best = v

            idx = off + d + 1
            if 0 <= idx < size:
                v = dp[idx]
                if v >= 0 and v < n and 0 <= v + d + 1 <= m:
                    cand = v + 1
                    if cand > best:
                        best = cand

            if best >= 0:
                y = best + d
                if best < n and 0 <= y < m:
                    best += lcp(best, y)
                ndp[off + d] = best
                if best == n and best + d == m:
                    print('Yes'); return
        dp = ndp

    print('No')

if __name__ == '__main__':
    solve()

import random


class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        max_run = 1
        cur = 1
        for i in range(1, n):
            if s[i] == s[i - 1]:
                cur += 1
                if cur > max_run:
                    max_run = cur
            else:
                cur = 1

        if max_run == 1:
            return 1
        if numOps == 0:
            return max_run

        arr = [1 if c == '1' else 0 for c in s]
        budget = numOps
        INF = budget + 1

        def feasible(L: int) -> bool:
            dp0 = [INF] * (L + 1)
            dp1 = [INF] * (L + 1)

            first = arr[0]
            dp0[1] = 0 if first == 0 else 1
            dp1[1] = 0 if first == 1 else 1

            if n == 1:
                return min(dp0[1], dp1[1]) <= budget

            for i in range(1, n):
                ch = arr[i]
                ndp0 = [INF] * (L + 1)
                ndp1 = [INF] * (L + 1)

                cost0 = 0 if ch == 0 else 1
                cost1 = 1 - cost0

                min0 = INF
                min1 = INF
                best0 = INF
                best1 = INF

                d0 = dp0
                d1 = dp1
                n0 = ndp0
                n1 = ndp1

                max_r = min(i, L)
                for r in range(1, max_r + 1):
                    v0 = d0[r]
                    if v0 < min0:
                        min0 = v0

                    v1 = d1[r]
                    if v1 < min1:
                        min1 = v1

                    if r < L:
                        if v0 <= budget:
                            nv = v0 + cost0
                            if nv < n0[r + 1]:
                                n0[r + 1] = nv
                                if nv < best0:
                                    best0 = nv

                        if v1 <= budget:
                            nv = v1 + cost1
                            if nv < n1[r + 1]:
                                n1[r + 1] = nv
                                if nv < best1:
                                    best1 = nv

                if min1 <= budget:
                    nv = min1 + cost0
                    if nv < n0[1]:
                        n0[1] = nv
                        if nv < best0:
                            best0 = nv

                if min0 <= budget:
                    nv = min0 + cost1
                    if nv < n1[1]:
                        n1[1] = nv
                        if nv < best1:
                            best1 = nv

                if best0 > budget and best1 > budget:
                    return False

                dp0, dp1 = ndp0, ndp1

            return best0 <= budget or best1 <= budget

        lo, hi = 1, max_run
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo


def brute_force(s: str, numOps: int) -> int:
    n = len(s)
    base = 0
    for i, c in enumerate(s):
        if c == '1':
            base |= 1 << i

    best = n
    for mask in range(1 << n):
        if bin(mask).count('1') > numOps:
            continue

        val = base ^ mask
        ans = 1
        cur = 1

        for i in range(1, n):
            if ((val >> i) & 1) == ((val >> (i - 1)) & 1):
                cur += 1
                if cur > ans:
                    ans = cur
            else:
                cur = 1

        if ans < best:
            best = ans
            if best == 1:
                break

    return best


def run_tests() -> None:
    sol = Solution()

    fixed_cases = [
        ("000001", 1, 2),
        ("0000", 2, 1),
        ("0101", 0, 1),
        ("0", 0, 1),
        ("1", 1, 1),
        ("00", 0, 2),
        ("00", 1, 1),
        ("000", 0, 3),
        ("000", 1, 1),
        ("00000", 0, 5),
        ("00000", 1, 2),
        ("00000", 2, 1),
        ("11111", 3, 1),
        ("000000", 3, 1),
        ("111111", 3, 1),
        ("0000000", 2, 2),
        ("0000000", 3, 1),
        ("1111111", 2, 2),
        ("1111111", 3, 1),
        ("00000000", 3, 2),
        ("00111100", 0, 4),
        ("01010", 5, 1),
    ]

    for s, ops, expected in fixed_cases:
        got = sol.minLength(s, ops)
        if got != expected:
            print(f"FAIL fixed case s={s} ops={ops} expected={expected} got={got}")
            raise RuntimeError("fixed case failed")

    # Exhaustive cross-check for all strings up to length 6.
    for n in range(1, 7):
        for mask in range(1 << n):
            s = ''.join('1' if (mask >> i) & 1 else '0' for i in range(n))
            for ops in range(n + 1):
                expected = brute_force(s, ops)
                got = sol.minLength(s, ops)
                if expected != got:
                    print(f"FAIL exhaustive s={s} ops={ops} expected={expected} got={got}")
                    raise RuntimeError("exhaustive test failed")

    # Random cross-check for slightly larger small strings.
    random.seed(20240527)
    for _ in range(200):
        n = random.randint(1, 10)
        s = ''.join(random.choice('01') for _ in range(n))
        ops = random.randint(0, n)
        expected = brute_force(s, ops)
        got = sol.minLength(s, ops)
        if expected != got:
            print(f"FAIL random s={s} ops={ops} expected={expected} got={got}")
            raise RuntimeError("random test failed")

    print("All tests passed")


if __name__ == "__main__":
    run_tests()

import sys
from bisect import bisect_right


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1
    x = int(data[idx]); idx += 1
    y = int(data[idx]); idx += 1

    houses = []
    for _ in range(N):
        hx = int(data[idx])
        hy = int(data[idx + 1])
        idx += 2
        houses.append((hx, hy))

    horizontal = {}
    vertical = {}

    for _ in range(M):
        d = data[idx]
        c = int(data[idx + 1])
        idx += 2

        ox, oy = x, y

        if d == b'U':
            y += c
        elif d == b'D':
            y -= c
        elif d == b'L':
            x -= c
        else:  # b'R'
            x += c

        if d == b'U' or d == b'D':
            if oy < y:
                a, b = oy, y
            else:
                a, b = y, oy
            vertical.setdefault(ox, []).append((a, b))
        else:
            if ox < x:
                a, b = ox, x
            else:
                a, b = x, ox
            horizontal.setdefault(y, []).append((a, b))

    del data

    def merge_intervals_by_key(groups):
        for key, intervals in groups.items():
            if len(intervals) == 1:
                s, e = intervals[0]
                groups[key] = ([s], [e])
                continue

            intervals.sort()
            starts = []
            ends = []

            cur_s, cur_e = intervals[0]
            for s, e in intervals[1:]:
                if s <= cur_e:
                    if e > cur_e:
                        cur_e = e
                else:
                    starts.append(cur_s)
                    ends.append(cur_e)
                    cur_s, cur_e = s, e

            starts.append(cur_s)
            ends.append(cur_e)
            groups[key] = (starts, ends)

    merge_intervals_by_key(horizontal)
    merge_intervals_by_key(vertical)

    count = 0
    br = bisect_right

    for hx, hy in houses:
        hit = False

        item = horizontal.get(hy)
        if item is not None:
            starts, ends = item
            i = br(starts, hx) - 1
            if i >= 0 and starts[i] <= hx <= ends[i]:
                hit = True

        if not hit:
            item = vertical.get(hx)
            if item is not None:
                starts, ends = item
                i = br(starts, hy) - 1
                if i >= 0 and starts[i] <= hy <= ends[i]:
                    hit = True

        if hit:
            count += 1

    sys.stdout.write(f"{x} {y} {count}\n")


if __name__ == "__main__":
    solve()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    n = int(data[0])
    adj = [[] for _ in range(n)]

    idx = 1
    for _ in range(n - 1):
        u = int(data[idx]) - 1
        v = int(data[idx + 1]) - 1
        idx += 2
        adj[u].append(v)
        adj[v].append(u)

    del data

    max_cap = 0
    for a in adj:
        cap = len(a) - 1
        if cap > max_cap:
            max_cap = cap

    buckets = [[] for _ in range(max_cap + 1)]
    for v, a in enumerate(adj):
        cap = len(a) - 1
        if cap >= 1:
            buckets[cap].append(v)

    cnt = [0] * n
    maxc = 0
    best = 0  # maximum kept vertices excluding the center

    for y in range(max_cap, 0, -1):
        for v in buckets[y]:
            for c in adj[v]:
                nv = cnt[c] + 1
                cnt[c] = nv
                if nv > maxc:
                    maxc = nv

        val = (y + 1) * maxc
        if val > best:
            best = val

    print(n - 1 - best)

if __name__ == "__main__":
    main()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Only values <= threshold can be incident to any edge.
        active = [x for x in nums if x <= threshold]
        if not active:
            return len(nums)

        parent = list(range(threshold + 1))
        rank = [0] * (threshold + 1)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> bool:
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return False
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1
            return True

        # rep[m] stores one active divisor of m, if any has been seen.
        rep = [0] * (threshold + 1)
        unions = 0
        t = threshold

        for d in active:
            for m in range(d, t + 1, d):
                r = rep[m]
                if r == 0:
                    rep[m] = d
                elif r != d:
                    if union(d, r):
                        unions += 1

        return len(nums) - unions
